public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Create an empty mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>();

    // Iterate over the vertices in the input graph
    for (V vertex : graph.vertexSet()) {
        // Add a mapping between the vertex and itself
        mapping.addMapping(vertex, vertex);
    }

    // Iterate over the edges in the input graph
    for (E edge : graph.edgeSet()) {
        // Get the source and target vertices for the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add a mapping between the edge and itself
        mapping.addMapping(edge, edge);

        // Add mappings between the source and target vertices and their corresponding copies
        mapping.addMapping(source, source);
        mapping.addMapping(target, target);
    }

    return mapping;
}

