private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the number of vertices in the graph is equal to the number of vertices in the set
    if (graph.vertexSet().size() != vertices.size()) {
        return false;
    }

    // Check if there is an edge between every pair of vertices in the set
    for (V source : vertices) {
        for (V target : vertices) {
            if (!graph.containsEdge(source, target)) {
                return false;
            }
        }
    }

    return true;
}

public List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int low = 0;
        int high = keys.size() - 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            K midKey = keys.get(mid);
            int cmp = midKey.compareTo(key);
            if (cmp < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        lowerBounds.add(low);
    }
    return lowerBounds;
}

